/** int → member name, for each table. */
export const NAMES = {
  Button: invert(Button),
  UiMode: invert(UiMode),
  PartyUiMode: invert(PartyUiMode),
  BiomeId: invert(BiomeId),
  StatusEffect: invert(StatusEffect),
  SaveSlotUiMode: invert(SaveSlotUiMode),
  SummaryUiMode: invert(SummaryUiMode),
  PartyOption: invert(PartyOption),
  AbilityAttr: invert(AbilityAttr),
  AbilityId: invert(AbilityId),
  AiType: invert(AiType),
  ArenaTagSide: invert(ArenaTagSide),
  BattleType: invert(BattleType),
  BattlerIndex: invert(BattlerIndex),
  BerryType: invert(BerryType),
  BiomePoolTier: invert(BiomePoolTier),
  Challenges: invert(Challenges),
  Command: invert(Command),
  EvoLevelThresholdKind: invert(EvoLevelThresholdKind),
  Gender: invert(Gender),
  HitResult: invert(HitResult),
  ModifierPoolType: invert(ModifierPoolType),
  ModifierTier: invert(ModifierTier),
  MoveCategory: invert(MoveCategory),
  MoveFlags: invert(MoveFlags),
  MoveId: invert(MoveId),
  MovePriorityInBracket: invert(MovePriorityInBracket),
  MoveResult: invert(MoveResult),
  MoveTarget: invert(MoveTarget),
  MoveUseMode: invert(MoveUseMode),
  MultiHitType: invert(MultiHitType),
  MysteryEncounterOptionMode: invert(MysteryEncounterOptionMode),
  MysteryEncounterTier: invert(MysteryEncounterTier),
  MysteryEncounterType: invert(MysteryEncounterType),
  Nature: invert(Nature),
  Passive: invert(Passive),
  PokeballType: invert(PokeballType),
  PokemonType: invert(PokemonType),
  SpeciesId: invert(SpeciesId),
  Stat: invert(Stat),
  TerrainType: invert(TerrainType),
  TimeOfDay: invert(TimeOfDay),
  TrainerPoolTier: invert(TrainerPoolTier),
  TrainerSlot: invert(TrainerSlot),
  WeatherType: invert(WeatherType),
} as const;

function invert(table: Record<string, number>): Record<number, string> {
  const out: Record<number, string> = {};
  for (const [k, v] of Object.entries(table)) out[v] = k;
  return out;
}
